[et_pb_section fb_built=&#8221;1&#8243; _builder_version=&#8221;4.27.6&#8243; _module_preset=&#8221;default&#8221; custom_margin=&#8221;0px|0px|0px|0px|true|true&#8221; custom_padding=&#8221;0px|0px|0px|0px|true|true&#8221; global_colors_info=&#8221;{}&#8221;][et_pb_row _builder_version=&#8221;4.27.6&#8243; _module_preset=&#8221;default&#8221; custom_margin=&#8221;0px|0px|0px|0px|true|true&#8221; custom_padding=&#8221;0px|0px|0px|0px|true|true&#8221; global_colors_info=&#8221;{}&#8221;][et_pb_column type=&#8221;4_4&#8243; admin_label=&#8221;Column&#8221; _builder_version=&#8221;4.27.6&#8243; _module_preset=&#8221;default&#8221; global_colors_info=&#8221;{}&#8221;][et_pb_code _builder_version=&#8221;4.27.6&#8243; _module_preset=&#8221;default&#8221; custom_margin=&#8221;0px|0px|0px|0px|true|true&#8221; custom_padding=&#8221;0px|0px|0px|0px|true|true&#8221; global_colors_info=&#8221;{}&#8221;]<style id="bh-home-css">
@import url('https://fonts.googleapis.com/css2?family=Poppins:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;1,500;1,600;1,700&display=swap');
html,body{overflow-x:hidden;}
.et_pb_section:has(.bh-home){padding:0 !important;}
.et_pb_row:has(.bh-home){padding:0 !important;width:100% !important;max-width:100% !important;}
.et_pb_column:has(.bh-home){padding:0 !important;}
.et_pb_text:has(.bh-home){margin:0 !important;padding:0 !important;}
#main-content:has(.bh-home) .container{padding-top:0 !important;margin-top:0 !important;}
article:has(.bh-home) .entry-content{margin:0 !important;padding:0 !important;}
p:has(> .bh-home){margin:0 !important;padding:0 !important;}
.bh-home{margin-top:0 !important;padding-top:0 !important;}
.bh-home > section:first-of-type,.bh-home > .bh-hero:first-of-type,.bh-home > .bh-topbar:first-child{margin-top:0 !important;}
.bh-home{
  /* Figma "Final File" tokens */
  --page:#EDEDED; --panel:#F8F9FA; --card:#FAFBF9;
  --ink:#333333; --p:#4F275C; --p2:#50305F; --deep:#2C1035;
  --sun:#FCB216; --sun2:#ffc23d;
  --mut:rgba(25,33,38,.7); --mut5:rgba(25,33,38,.5); --line:rgba(25,33,38,.1);
  --gray:#7B7575; --hero-ink:#F4F4F4;
  --r:13px; --r-sm:7px; --r-lg:22px;
  
  --fs-h2:clamp(23px,2.462vw,40px); --fs-mid:clamp(19px,1.984vw,32px); --fs-h3:clamp(19px,1.984vw,32px);
  --fs-cardh:clamp(17px,1.778vw,29px); --fs-body:clamp(13.5px,1.368vw,22px); --fs-sub:clamp(13.5px,1.368vw,22px);
  --fs-btn:clamp(13.5px,1.231vw,20px); --fs-btn-lg:clamp(15px,1.642vw,27px); --fs-tab:clamp(13px,1.231vw,20px);
  --fs-cardt:clamp(14px,1.231vw,20px); --fs-cardb:clamp(12px,1.026vw,17px);
  --fs-meta:clamp(12px,1.094vw,17.5px); --fs-micro:clamp(10.5px,.889vw,14.5px); --fs-stat:clamp(16px,2.052vw,33px);
  --sh-card:0.1px 0.1px 4px rgba(0,0,0,.1);
  --sh-soft:0 4px 4px rgba(123,117,117,.1);
  --sh-post:-3px 3px 4px rgba(0,0,0,.25);
  --sans:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,sans-serif;
  font-family:var(--sans); color:var(--ink); line-height:1.5;
  background:var(--page);
  -webkit-font-smoothing:antialiased;
  width:100vw; max-width:100vw; position:relative; left:50%; right:50%;
  margin-left:-50vw; margin-right:-50vw; overflow-x:clip;
}
.bh-home *{box-sizing:border-box;}
.bh-home h1,.bh-home h2,.bh-home h3,.bh-home h4,.bh-home h5,.bh-home h6,.bh-home p,.bh-home a,.bh-home span,.bh-home button,.bh-home div,.bh-home li,.bh-home .bh-h2{font-family:var(--sans) !important;}
.bh-home img{max-width:100%;display:block;}
.bh-home a{text-decoration:none;color:inherit;}
.bh-wrap{max-width:min(1660px,92vw);margin:0 auto;padding:0 clamp(24px,3.42vw,60px);width:100%;}
@media(max-width:640px){.bh-wrap{padding:0 16px;}div#bh-concernPanels{margin:0 -6px;}}
.bh-section{padding:clamp(66px,10.3vw,152px) 0;position:relative;}
@media(max-width:980px){.bh-section{padding:46px 0;}}
@media(max-width:640px){.bh-section{padding:40px 0;}}
.bh-photo{position:absolute;inset:0;background-image:var(--img);background-size:cover;background-position:center;background-color:transparent;}
.bh-photo.bh-contain{background-size:contain;background-position:center;background-repeat:no-repeat;background-color:transparent;}
.bh-home > section,.bh-home > .bh-hero{position:relative;z-index:1;}
.bh-blob{display:none;}
.bh-sec-eyerow{display:flex;justify-content:space-between;align-items:center;gap:clamp(10px,1.2vw,18px);margin-bottom:clamp(10px,1.2vw,20px);}
.bh-eyebrow2{display:inline-flex;align-items:center;gap:7px;font-size:var(--fs-meta) !important;font-weight:500;letter-spacing:.0em;text-transform:uppercase;color:var(--p2);font-style:italic;}
.bh-eyebrow2 strong,.bh-eyebrow2 b{color:var(--ink);font-weight:500;}
.bh-eyebrow2::before{content:'';width:10px;height:10px;border-radius:3px;background:var(--p2);flex:0 0 auto;}
.bh-eyebrow{display:inline-flex;align-items:center;background:rgba(252,178,22,.16);color:var(--p2);font-size:var(--fs-micro);font-weight:700;letter-spacing:.14em;text-transform:uppercase;padding:.5em 1.1em;border-radius:999px;margin-bottom:.5em;}
/* Headings: Poppins Regular with SemiBold <strong> spans (Figma: 22/28, -0.22px) */
.bh-h2{font-weight:400;font-size:var(--fs-h2) !important;line-height:1.28 !important;letter-spacing:-.01em;color:var(--ink);margin:0;padding:0;}
.bh-h2 strong,.bh-h2 b{font-weight:600;}
.bh-h2 em{font-style:normal;color:var(--sun);}
.bh-sub{color:var(--mut);font-size:var(--fs-sub) !important;line-height:1.5 !important;letter-spacing:-.01em;margin:.6em 0 0;max-width:100%;font-weight:400;}
.bh-sec-head{display:flex;align-items:flex-end;justify-content:space-between;gap:clamp(16px,2vw,34px);margin-bottom:clamp(20px,2.4vw,40px);}
.bh-sec-head>div{min-width:0;}
.bh-sec-actions{display:flex;gap:12px;align-items:center;flex:0 0 auto;}
.bh-arrows{display:flex;gap:8px;}
@media(max-width:640px){.bh-sec-head{gap:8px;margin-bottom:18px;}}
/* Buttons: Figma small gold CTA (31px tall, 7px radius, white 13px Medium) */
.bh-btn{display:inline-flex;align-items:center;justify-content:center;gap:clamp(6px,.55vw,10px);border-radius:clamp(7px,.62vw,10px);padding:clamp(9px,.75vw,13px) clamp(18px,1.85vw,32px);font-weight:500;font-size:var(--fs-btn);line-height:1;font-family:var(--sans);cursor:pointer;border:0;transition:transform .3s cubic-bezier(.22,1,.36,1),box-shadow .3s,background .3s;white-space:nowrap;}
.bh-btn:hover{transform:translateY(-2px);}
.bh-btn-gold{background:var(--sun);color:#fff !important;}
.bh-btn-gold:hover{background:var(--sun2);}
.bh-btn-ink{color:#192126;}
.bh-btn-white{background:#fff;color:var(--p);box-shadow:var(--sh-card);}
.bh-btn-lg{padding:clamp(11px,.9vw,16px) clamp(22px,2.2vw,38px);}
.bh-link-more{font-weight:400;font-size:var(--fs-meta);color:var(--mut);white-space:nowrap;display:inline-flex;align-items:center;gap:3px;}
.bh-link-more:hover{color:var(--p);}
.bh-link-more svg{width:14px;height:14px;}
.bh-arrow{width:40px;height:40px;border-radius:50%;border:1px solid var(--line);background:#fff;color:var(--p);display:inline-flex;align-items:center;justify-content:center;cursor:pointer;transition:all .25s;flex:0 0 auto;}
.bh-arrow:hover{background:var(--p);color:#fff;border-color:var(--p);transform:scale(1.08);}
.bh-track-foot{display:none !important;}
@media(max-width:760px){.bh-track-foot{display:none;}}
.bh-track{display:flex;overflow-x:auto;scrollbar-width:none;-ms-overflow-style:none;cursor:grab;}
.bh-track::-webkit-scrollbar{display:none;}
.bh-track.bh-drag{cursor:grabbing;}
.bh-track.bh-drag *{pointer-events:none;}
.bh-ribbon{display:inline-flex;align-items:center;gap:7px;background:var(--p2);color:#fff;font-size:var(--fs-meta);font-weight:500;padding:9px 16px;border-radius:8px;line-height:1.1;}
.bh-ribbon-try{display:inline-flex;align-items:center;gap:4px;font-size:var(--fs-micro);font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--sun);}
.bh-ribbon b{font-weight:700;color:#fff;}
.bh-ribbon .bh-kit{color:rgba(255,255,255,.72);}
/* mini section label (Physio's we work with) */
.bh-mini-h{font-size:var(--fs-meta);font-weight:500;color:#515151;margin:0 0 10px;}

@keyframes bhIn{from{opacity:0;transform:translateY(24px);}to{opacity:1;transform:none;}}
@keyframes bhFadeIn{from{opacity:0;}to{opacity:1;}}
@keyframes bhPop{0%{transform:scale(.4);}70%{transform:scale(1.12);}100%{transform:scale(1);}}
.bh-reveal.in{animation:bhIn .7s cubic-bezier(.22,1,.36,1) backwards;}
.bh-reveal.in,.bh-fade.in,.bh-stagger.in>*{animation-iteration-count:1 !important;animation-fill-mode:backwards;}
.bh-fade.in{animation:bhFadeIn .9s ease backwards;}
.bh-stagger.in>*{animation:bhIn .55s cubic-bezier(.22,1,.36,1) backwards;}
.bh-stagger.in>*:nth-child(2){animation-delay:.06s;}
.bh-stagger.in>*:nth-child(3){animation-delay:.12s;}
.bh-stagger.in>*:nth-child(4){animation-delay:.18s;}
.bh-stagger.in>*:nth-child(5){animation-delay:.24s;}
.bh-stagger.in>*:nth-child(6){animation-delay:.3s;}
.bh-stagger.in>*:nth-child(7){animation-delay:.36s;}
.bh-stagger.in>*:nth-child(8){animation-delay:.42s;}
@media(prefers-reduced-motion:reduce){.bh-reveal.in,.bh-fade.in,.bh-stagger.in>*{animation:none !important;}}
/* HERO (purple, rounded bottom-right, copy bottom-left) */
.bh-hero{position:relative;background:var(--panel);}
.bh-hero-slider{position:relative;height:clamp(460px,35.5vw,640px);overflow:hidden;background:var(--p);cursor:grab;touch-action:pan-y;border-radius:0 0 clamp(146px,15vw,220px) 0;}
.bh-hero-slider.bh-hero-dragging{cursor:grabbing;user-select:none;}
.bh-hero-slider.bh-hero-dragging .bh-hero-slide.is-active{transition:none;}
@media(max-width:640px){.bh-hero-slider{height:515px;border-radius:0 0 146px 0;}}
.bh-hero-slide{position:absolute;inset:0;opacity:0;transition:opacity 1s cubic-bezier(.22,1,.36,1);pointer-events:none;}
.bh-hero-slide.is-active{opacity:1;pointer-events:auto;}
@keyframes bhHeroIn{from{opacity:0;transform:translateY(26px);}to{opacity:1;transform:none;}}
.bh-hero-slide.is-active h1{animation:bhHeroIn .8s .1s cubic-bezier(.22,1,.36,1) backwards;}
.bh-hero-slide.is-active p{animation:bhHeroIn .8s .25s cubic-bezier(.22,1,.36,1) backwards;}
.bh-hero-slide.is-active .bh-hero-cta{animation:bhHeroIn .8s .4s cubic-bezier(.22,1,.36,1) backwards;}
@media(prefers-reduced-motion:reduce){.bh-hero-slide.is-active h1,.bh-hero-slide.is-active p,.bh-hero-slide.is-active .bh-hero-cta{animation:none !important;}}
.bh-hero-pic{position:absolute;inset:0;display:block;}
.bh-hero-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;image-rendering:auto;backface-visibility:hidden;transform:translateZ(0);}

/*.bh-hero-slide::after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(44,16,53,0) 42%,rgba(44,16,53,.55) 100%);}*/
.bh-hero-inner{position:relative;z-index:2;height:100%;display:flex;align-items:flex-end;justify-content:flex-start;text-align:left;padding:0 31px 92px;}
.bh-hero-copy{max-width:720px;}
.bh-hero-kicker{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.28);color:#ffe9c4;font-size:var(--fs-micro);font-weight:600;letter-spacing:.12em;text-transform:uppercase;padding:8px 16px;border-radius:999px;margin-bottom:14px;}
.bh-hero-copy h1{font-weight:400;font-size:clamp(23.0px,3.215vw,53.0px) !important;line-height:1.04;letter-spacing:-.01em;color:var(--hero-ink);margin:0 0 10px;}
.bh-hero-copy h1 strong,.bh-hero-copy h1 b{font-weight:700;}
.bh-hero-copy h1 em{font-style:normal;color:var(--sun);}
.bh-hero-copy p{color:var(--hero-ink);font-size:clamp(12.0px,1.71vw,28.0px) !important;line-height:1.12;letter-spacing:-.01em;max-width:none;margin:0 0 22px;}
@media(min-width:861px){.bh-hero-copy p{white-space:nowrap;}.bh-hero-copy p:has(br.bh-br-d),.bh-hero-copy p:has(br.bh-br-a){white-space:normal;}}
/* line-break control: [br] always, [brd] desktop+tablet, [brm] mobile */
.bh-home br.bh-br-a{display:inline !important;}
.bh-home br.bh-br-d{display:none !important;}
.bh-home br.bh-br-m{display:inline !important;}
@media(min-width:861px){
  .bh-home br{display:none !important;}
  .bh-home br.bh-br-a{display:inline !important;}
  .bh-home br.bh-br-d{display:inline !important;}
  .bh-home br.bh-br-m{display:none !important;}
}
@media(min-width:641px) and (max-width:860px){
  .bh-home br{display:none !important;}
  .bh-home br.bh-br-a,.bh-home br.bh-br-m{display:inline !important;}
}
.bh-hero-cta{display:flex;gap:12px;flex-wrap:wrap;justify-content:flex-start;}
@media(min-width:981px){.bh-home .bh-hero-cta .bh-btn{font-size:var(--fs-btn-lg);height:clamp(38px,3.1vw,51px);min-width:clamp(220px,19.5vw,320px);padding:0 clamp(26px,1.8vw,32px);border-radius:10px;font-weight:500;}}
@media(min-width:981px){.bh-hero-inner{align-items:center;padding-left:max(24px,max(24px,calc((100vw - min(1540px,86.3vw))/2)));padding-right:24px;padding-bottom:74px;}.bh-hero-copy{margin:0;max-width:720px;}}
.bh-hero-nav{display:none;}
.bh-hero-dots{position:absolute;left:0;right:0;bottom:22px;display:flex;justify-content:center;gap:8px;z-index:5;}
.bh-hero-dot{width:8px;height:8px;border-radius:999px;border:0;background:rgba(255,255,255,.5);cursor:pointer;padding:0;transition:all .4s cubic-bezier(.22,1,.36,1);}
.bh-hero-dot.is-active{width:28px;background:var(--sun);}
.bh-hero-progress{position:absolute;left:0;right:0;top:0;height:3px;background:rgba(255,255,255,.14);z-index:5;}
.bh-hero-progress span{display:block;height:100%;width:0;background:var(--sun);}
/* PRODUCT RANGE TILES (3 small white cards over the hero edge) */
.bh-range{position:relative;z-index:4;margin-top:-58px;padding:0 0 24px;}
.bh-range::before{content:'';position:absolute;left:0;right:0;top:58px;bottom:0;background:var(--panel);}
.bh-range-track{position:relative;z-index:1;gap:15px;padding:6px 22px 12px;}
@media(min-width:1248px){.bh-range-track{padding-left:max(24px,calc((100vw - min(1540px,86.3vw))/2));padding-right:max(24px,calc((100vw - min(1540px,86.3vw))/2));}}
.bh-prodtile{position:relative;flex:0 0 clamp(101px,10.5vw,148px);aspect-ratio:101/107;min-height:107px;border-radius:8.3px;overflow:hidden;background:#fff;border:.71px solid rgba(0,0,0,.1);box-shadow:var(--sh-card);transition:transform .45s cubic-bezier(.22,1,.36,1),box-shadow .45s;}
@media(max-width:640px){.bh-prodtile{flex:0 0 calc((100vw - 74px)/3);}}
.bh-prodtile:hover{transform:translateY(-5px);box-shadow:0 10px 22px rgba(36,14,43,.14);}
.bh-prodtile .bh-photo{transition:transform .7s cubic-bezier(.22,1,.36,1);}
.bh-prodtile:hover .bh-photo{transform:scale(1.06);}
.bh-prodtile::after{content:'';position:absolute;left:-5%;right:-5%;bottom:0;height:75%;background:linear-gradient(180deg,rgba(0,0,0,0),rgba(30,30,30,.4));z-index:1;}
.bh-prodtile-label{position:absolute;left:8px;bottom:8px;z-index:2;color:#fff;font-weight:500;font-size:var(--fs-sub);line-height:1.25;max-width:88%;text-shadow:0 1px 6px rgba(30,30,30,.45);}
.bh-best{position:absolute;top:7px;left:7px;background:var(--sun);color:#192126;font-size:var(--fs-micro);font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:4px 8px;border-radius:999px;z-index:3;}
.bh-view{position:absolute;right:8px;bottom:8px;z-index:3;background:rgba(255,255,255,.95);color:var(--p);font-size:var(--fs-micro);font-weight:600;padding:6px 12px;border-radius:999px;opacity:0;transform:translateY(8px);transition:all .35s cubic-bezier(.22,1,.36,1);}
.bh-prodtile:hover .bh-view{opacity:1;transform:none;}
@media(hover:none){.bh-view{display:none;}}
/* TRUST BAR (flat on the page, dividers between stats) */
.bh-trust{background:var(--page);padding:clamp(26px,4vw,52px) 0 clamp(34px,4.5vw,56px);}
.bh-trust-inner{display:grid;grid-template-columns:repeat(4,1fr);background:transparent;border:0;border-radius:0;padding:0;box-shadow:none;}
.bh-stat{text-align:center;padding:4px 6px;position:relative;transition:transform .3s cubic-bezier(.22,1,.36,1);}
.bh-stat:hover{transform:translateY(-3px);}
.bh-stat + .bh-stat::before{content:'';position:absolute;left:0;top:50%;transform:translateY(-50%);height:17px;width:1px;background:rgba(178,178,178,.8);}
.bh-stat-num{display:inline-flex;align-items:center;gap:3px;justify-content:center;font-weight:600;font-size:var(--fs-stat);color:var(--p2);line-height:1.2;}
.bh-stat-num svg{color:var(--sun);width:1.3em;height:1.3em;}
.bh-stat-label{font-size:var(--fs-sub);color:var(--mut5);font-weight:500;margin-top:3px;line-height:1.18;}
/* range header (renders only when the label/link fields are filled) */
.bh-range-headwrap{position:relative;z-index:2;}
.bh-range-head{padding:70px 24px 6px;display:flex;align-items:flex-end;justify-content:space-between;gap:12px;}
/* reel chips (render only when tag/length are filled) */
.bh-reel-tag{position:absolute;top:10px;left:10px;z-index:3;background:rgba(18,18,18,.55);color:#fff;font-size:var(--fs-micro);font-weight:500;letter-spacing:.02em;padding:4px 10px;border-radius:999px;backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px);}
.bh-reel-len{position:absolute;top:11px;right:10px;z-index:3;background:rgba(18,18,18,.55);color:#fff;font-size:var(--fs-micro);font-weight:500;padding:3px 7px;border-radius:6px;}
.bh-reel-thumb.is-playing .bh-reel-tag,.bh-reel-thumb.is-playing .bh-reel-len{display:none;}
.bh-reel-ver{display:inline-block;vertical-align:-1px;margin-left:4px;}
/* category overlay (renders only when "Show name & Shop Now" is on) */
.bh-catrow{position:relative;}
.bh-catrow-ov{position:absolute;left:0;right:0;bottom:0;z-index:2;display:flex;flex-direction:column;gap:2px;padding:26px 16px 14px;background:linear-gradient(180deg,rgba(10,10,10,0) 0%,rgba(10,10,10,.62) 78%);border-radius:0 0 12px 12px;pointer-events:none;}
.bh-catrow-lbl{font-size:var(--fs-micro);font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--sun);}
.bh-catrow-name{font-size:var(--fs-cardh);font-weight:600;color:#fff;line-height:1.2;}
.bh-catrow-tg{font-size:var(--fs-meta);color:rgba(255,255,255,.85);line-height:1.3;}
.bh-catrow-ct{font-size:var(--fs-micro);color:rgba(255,255,255,.75);margin-top:1px;}
/* SHOP BY CONCERN (light card, pills, banner, product strip) */
.bh-concern{background:var(--panel);border:.71px solid var(--line);border-radius:14px;box-shadow:var(--sh-card);padding:clamp(44px,5.5vw,76px) 0 clamp(48px,6vw,80px);}
.bh-concern .bh-sub{color:var(--gray);}
.bh-concern-bar{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;margin:22px 0 0;position:relative;z-index:2;}
.bh-concern-menu{display:flex;gap:0;overflow-x:auto;scrollbar-width:none;padding:0 0 0 clamp(10px,1.1vw,18px);align-items:center;flex:1;min-width:0;margin-left:0px;overflow-y:hidden;}
.bh-concern-menu::-webkit-scrollbar{display:none;}
.bh-cmenu-item{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:0;background:transparent;border:0;border-radius:5px;margin:0 clamp(3px,.38vw,7px);padding:14px 9px;cursor:pointer;font-family:var(--sans);font-size:var(--fs-tab);font-weight:400;color:var(--mut);transition:all .35s cubic-bezier(.22,1,.36,1);flex:0 1 auto;line-height:1.1;white-space:nowrap;}
@media(max-width:860px){.bh-cmenu-item{padding:14px;font-size:13px;flex:0 0 auto;}}
.bh-cmenu-item:hover{color:var(--ink);}
